process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
const WP='https://dev.avesa.lt';
const AUTH='Basic '+Buffer.from((process.env.WP_USER||'').trim()+':'+(process.env.WP_APP_PASS||'').trim()).toString('base64');
const GH=process.env.GH_TOKEN, REPO=process.env.GH_REPO;
const AKC='';
const DEP=Buffer.from('','base64').toString();
async function putRaw(path,b64,msg){
  const url=`https://api.github.com/repos/${REPO}/contents/${path}`;
  let sha; try{ const r=await fetch(url,{headers:{Authorization:`Bearer ${GH}`}}); if(r.ok) sha=(await r.json()).sha; }catch(e){}
  const body={message:msg||'akc6', content:b64}; if(sha) body.sha=sha;
  await fetch(url,{method:'PUT',headers:{Authorization:`Bearer ${GH}`,'Content-Type':'application/json'},body:JSON.stringify(body)});
}
const putJson=(p,o)=>putRaw(p, Buffer.from(JSON.stringify(o,null,2)).toString('base64'),'akc6');
async function snip(name,code){
  const r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{method:'POST',
    headers:{Authorization:AUTH,'Content-Type':'application/json'},
    body:JSON.stringify({name, code, scope:'global', active:true})});
  return await r.json();
}
async function off(id){ await fetch(`${WP}/wp-json/code-snippets/v1/snippets/${id}`,{method:'POST',
  headers:{Authorization:AUTH,'Content-Type':'application/json'},body:JSON.stringify({active:false})}); }
const pause=ms=>new Promise(x=>setTimeout(x,ms));
async function main(){
  const out={VERSIJA:'AKC6'};
  let r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const list=await r.json();
  for(const t of (Array.isArray(list)?list:[]).filter(s=>s.active&&/^TEMP/i.test(s.name||''))){ await off(t.id); }
  let s=await snip('TEMP akc6 set', "update_option('ps_uxd_akc','"+AKC+"','no');");
  await pause(2000); await fetch(`${WP}/`,{headers:{Authorization:AUTH}}); await off(s.id);
  const sd=await snip('TEMP akc6 deploy', DEP.replace(/^<\?php\s*/,''));
  await pause(2500);
  let resp=await fetch(`${WP}/?ps_uxd6=1&k=dq7m3z`,{headers:{Authorization:AUTH}});
  try{ out.deploy=JSON.parse(await resp.text()); }catch(e){ out.deploy_raw='nejson'; }

  const {chromium}=await import('playwright');
  const br=await chromium.launch();
  const ctx=await br.newContext({ignoreHTTPSErrors:true, viewport:{width:1680,height:1050}});
  const page=await ctx.newPage();
  const jsErr=[]; page.on('pageerror',e=>jsErr.push(String(e)));
  page.setDefaultTimeout(12000);
  page.on('dialog',async d=>{ out.dialogas=(d.message()||'').slice(0,120); await d.accept(); });

  await page.goto(`${WP}/?ps_uxlog2=1&k=dq7m3z`,{waitUntil:'networkidle',timeout:60000});
  await pause(1800);
  out.brendu=await page.evaluate(()=>document.querySelectorAll('.varneles[data-sar=brendai] label').length);

  /* Ambrosia -15%, perziura */
  out.pazymeta=await page.evaluate(()=>{
    document.querySelector('.f-pav').value='Ambrosia rugpjūtis −15 %';
    document.querySelector('.f-reiksme').value='15';
    const labels=document.querySelectorAll('.varneles[data-sar=brendai] label');
    for(const l of labels){ if(l.textContent.toLowerCase().indexOf('ambrosia')>=0){ l.querySelector('input').checked=true; return l.textContent.trim(); } }
    return null;
  });
  await page.evaluate(()=>document.querySelector('.ak-perziureti').click());
  await pause(5000);
  out.perziura=await page.evaluate(()=>{
    const s=document.querySelector('.perz-suv'), t=document.querySelector('.perz-turinys');
    const eil=t?Array.prototype.slice.call(t.querySelectorAll('.pt tbody tr')).slice(0,4).map(tr=>tr.innerText.replace(/\n+/g,' | ').slice(0,160)):[];
    return {suvestine:s?s.innerText.replace(/\n+/g,' | '):null, eiluciu:t?t.querySelectorAll('.pt tbody tr').length:0, pvz:eil};
  });
  let png=await page.screenshot(); out.s1=await putRaw('screenshots/akc6_perziura.png', png.toString('base64'),'akc6');

  /* Datos + issaugojimas */
  await page.evaluate(()=>{
    const d=new Date(); const p=n=>String(n).padStart(2,'0');
    const f=(x)=>x.getFullYear()+'-'+p(x.getMonth()+1)+'-'+p(x.getDate())+'T'+p(x.getHours())+':'+p(x.getMinutes());
    const iki=new Date(d.getTime()+7*86400000);
    document.querySelector('.f-nuo').value=f(d);
    document.querySelector('.f-iki').value=f(iki);
  });
  await page.evaluate(()=>document.querySelector('.ak-issaugoti').click());
  await pause(4000);
  out.po_issaugojimo=page.url();
  out.stat=await page.evaluate(()=>{ const s=document.querySelector('.ak-stat'); return s?s.textContent:null; });
  png=await page.screenshot(); out.s2=await putRaw('screenshots/akc6_issaugota.png', png.toString('base64'),'akc6');

  out.js_klaidos=jsErr.slice(0,8);
  await br.close(); await off(sd.id);
  r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const l2=await r.json();
  out.liko_temp=(Array.isArray(l2)?l2:[]).filter(x=>x.active&&/^TEMP/i.test(x.name||'')).map(x=>x.name);
  await putJson('analize/akc6.json', out);
}
main().catch(async e=>{ await putJson('analize/akc6.json',{klaida:String(e).slice(0,400)}); });
